    {
        return 2;
    }
#endif
    bool bench = argc == 2 && std::strcmp(argv[1], "benchmark") == 0;
    test_ins_reset<float>(bench);
    test_ins_reset<double>(bench);
    test_ins_horizontal_position_cross<float>(bench);
